UPDATE questions SET data=$question_json${"id":"10g3-w9-p730-q37","classroom":"10G3","examWeek":9,"position":5,"type":"MCQ","exam":"EOT · 10G3 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 730 · Q37 · Quadratic reasoning · الاستدلال التربيعي","prompt":"Which expression is not a perfect-square trinomial?","promptAr":"أي عبارة ليست ثلاثية حدود تمثل مربعاً كاملاً؟","answer":"D does not belong. A $=(n-\\frac12)^2$, B $=(n+\\frac12)^2$, and C $=(n-\\frac13)^2$. In D, half the linear coefficient is $\\frac16$, whose square is $\\frac1{36}$, not $\\frac19$. Therefore D is not a perfect-square trinomial.","answerAr":"العبارة D لا تنتمي. فالعبارة A تساوي $(n-\\frac12)^2$، وB تساوي $(n+\\frac12)^2$، وC تساوي $(n-\\frac13)^2$. في D نصف معامل n هو $\\frac16$ ومربعه $\\frac1{36}$ وليس $\\frac19$؛ لذا ليست مربعاً كاملاً.","marks":1,"diagram":"none","difficulty":"Standard","image":"","options":["$n^2-n+\\frac14$","$n^2+n+\\frac14$","$n^2-\\frac23n+\\frac19$","$n^2+\\frac13n+\\frac19$"],"optionsAr":["$n^2-n+\\frac14$","$n^2+n+\\frac14$","$n^2-\\frac23n+\\frac19$","$n^2+\\frac13n+\\frac19$"],"sourcePage":730,"sourceQuestion":37,"problemData":{"kind":"odd-one-out","coefficients":[[1,-1,0.25],[1,1,0.25],[1,-0.6666666666666666,0.1111111111111111],[1,0.3333333333333333,0.1111111111111111]],"oddIndex":3},"sourceKind":"reasoning","correctIndex":3}$question_json$::jsonb,revision=revision+1,updated_at=now() WHERE id='10g3-w9-p730-q37' AND NOT deleted AND data=$question_json${"id":"10g3-w9-p730-q37","classroom":"10G3","examWeek":9,"position":5,"type":"FRQ","exam":"EOT · 10G3 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 730 · Q37 · Quadratic reasoning · الاستدلال التربيعي","prompt":"Which expression does not belong with the other three? Explain your reasoning by checking whether each is a perfect square.\nA. $n^2-n+\\frac14$\nB. $n^2+n+\\frac14$\nC. $n^2-\\frac23n+\\frac19$\nD. $n^2+\\frac13n+\\frac19$","promptAr":"أي عبارة لا تنتمي إلى العبارات الثلاث الأخرى؟ علّل بالتحقق مما إذا كانت كل عبارة مربعاً كاملاً.\nA. $n^2-n+\\frac14$\nB. $n^2+n+\\frac14$\nC. $n^2-\\frac23n+\\frac19$\nD. $n^2+\\frac13n+\\frac19$","answer":"D does not belong. A $=(n-\\frac12)^2$, B $=(n+\\frac12)^2$, and C $=(n-\\frac13)^2$. In D, half the linear coefficient is $\\frac16$, whose square is $\\frac1{36}$, not $\\frac19$. Therefore D is not a perfect-square trinomial.","answerAr":"العبارة D لا تنتمي. فالعبارة A تساوي $(n-\\frac12)^2$، وB تساوي $(n+\\frac12)^2$، وC تساوي $(n-\\frac13)^2$. في D نصف معامل n هو $\\frac16$ ومربعه $\\frac1{36}$ وليس $\\frac19$؛ لذا ليست مربعاً كاملاً.","marks":4,"diagram":"none","difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":730,"sourceQuestion":37,"responseParts":[{"label":"Expression that does not belong · العبارة المختلفة"},{"label":"Reason and square forms · التعليل وصور المربعات"}],"problemData":{"kind":"odd-one-out","coefficients":[[1,-1,0.25],[1,1,0.25],[1,-0.6666666666666666,0.1111111111111111],[1,0.3333333333333333,0.1111111111111111]],"oddIndex":3},"sourceKind":"reasoning"}$question_json$::jsonb;
UPDATE questions SET data=$question_json${"id":"10g3-w9-p730-q38","classroom":"10G3","examWeek":9,"position":6,"type":"MCQ","exam":"EOT · 10G3 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 730 · Q38 · Quadratic reasoning · الاستدلال التربيعي","prompt":"Which quadratic equation has 4 as its only solution?","promptAr":"أي معادلة تربيعية حلها الوحيد هو 4؟","answer":"One example is $(x-4)^2=0$, or $x^2-8x+16=0$. Taking square roots gives $x-4=0$, hence $x=4$, a repeated root. Any equation $a(x-4)^2=0$ with $a\\ne0$ is acceptable.","answerAr":"مثال صحيح: $(x-4)^2=0$، أي $x^2-8x+16=0$. بأخذ الجذر التربيعي نحصل على $x-4=0$، ومنه $x=4$ وهو جذر مكرر. تُقبل أي معادلة $a(x-4)^2=0$ حيث $a\\ne0$.","marks":1,"diagram":"none","difficulty":"Standard","image":"","options":["$(x-4)^2=0$","$(x+4)^2=0$","$x^2-16=0$","$x^2+16=0$"],"optionsAr":["$(x-4)^2=0$","$(x+4)^2=0$","$x^2-16=0$","$x^2+16=0$"],"sourcePage":730,"sourceQuestion":38,"expectedValues":{"root":4},"problemData":{"kind":"create-equation","exampleCoefficients":[1,-8,16]},"sourceKind":"reasoning","correctIndex":0}$question_json$::jsonb,revision=revision+1,updated_at=now() WHERE id='10g3-w9-p730-q38' AND NOT deleted AND data=$question_json${"id":"10g3-w9-p730-q38","classroom":"10G3","examWeek":9,"position":6,"type":"FRQ","exam":"EOT · 10G3 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 730 · Q38 · Quadratic reasoning · الاستدلال التربيعي","prompt":"Write a quadratic equation for which the only solution is 4. Explain why it has no other solution.","promptAr":"اكتب معادلة تربيعية حلها الوحيد هو 4، وفسّر لماذا لا يوجد حل آخر.","answer":"One example is $(x-4)^2=0$, or $x^2-8x+16=0$. Taking square roots gives $x-4=0$, hence $x=4$, a repeated root. Any equation $a(x-4)^2=0$ with $a\\ne0$ is acceptable.","answerAr":"مثال صحيح: $(x-4)^2=0$، أي $x^2-8x+16=0$. بأخذ الجذر التربيعي نحصل على $x-4=0$، ومنه $x=4$ وهو جذر مكرر. تُقبل أي معادلة $a(x-4)^2=0$ حيث $a\\ne0$.","marks":3,"diagram":"none","difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":730,"sourceQuestion":38,"responseParts":[{"label":"Quadratic equation · المعادلة التربيعية"},{"label":"Explain the repeated root · تفسير الجذر المكرر"}],"expectedValues":{"root":4},"problemData":{"kind":"create-equation","exampleCoefficients":[1,-8,16]},"sourceKind":"reasoning"}$question_json$::jsonb;
UPDATE questions SET data=$question_json${"id":"10g3-w9-p730-q39","classroom":"10G3","examWeek":9,"position":7,"type":"MCQ","exam":"EOT · 10G3 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 730 · Q39 · Quadratic reasoning · الاستدلال التربيعي","prompt":"Which comparison is correct for solving $x^2-5x-7=0$?","promptAr":"أي مقارنة صحيحة لحل $x^2-5x-7=0$؟","answer":"Completing the square: $x^2-5x=7$, then $x^2-5x+\\frac{25}{4}=\\frac{53}{4}$, so $(x-\\frac52)^2=\\frac{53}{4}$. Thus $x=\\frac{5\\pm\\sqrt{53}}2$. Graphing $y=x^2-5x-7$ gives approximate x-intercepts $(-1.14,0)$ and $(6.14,0)$. The discriminant is 53, not a rational square, so the polynomial does not factor into linear factors with rational coefficients. Real radical factors exist, but are less convenient to find directly. Completing the square is efficient for exact answers; graphing checks the approximate roots.","answerAr":"بإكمال المربع: $x^2-5x=7$، ثم $x^2-5x+\\frac{25}{4}=\\frac{53}{4}$، ولذلك $(x-\\frac52)^2=\\frac{53}{4}$. إذن $x=\\frac{5\\pm\\sqrt{53}}2$. يعطي رسم $y=x^2-5x-7$ التقاطعين التقريبيين $(-1.14,0)$ و$(6.14,0)$. المميز 53 ليس مربع عدد نسبي، فلا تتحلل كثيرة الحدود إلى عوامل خطية بمعاملات نسبية. يمكن كتابتها بعوامل جذرية حقيقية، لكن إيجادها مباشرة أقل سهولة. إكمال المربع مناسب للحلول الدقيقة، والرسم للتحقق التقريبي.","marks":1,"diagram":"none","difficulty":"Standard","image":"","options":["Completing the square gives $(x-5)^2=32$, so $x=5\\pm\\sqrt{32}$.","Completing the square gives $x=\\frac{5\\pm\\sqrt{53}}2$; graphing gives approximately −1.14 and 6.14; no rational linear factors.","Factoring gives $(x-7)(x+1)=0$, so the solutions are 7 and −1.","There are no real solutions because integer factoring is impossible."],"optionsAr":["بإكمال المربع $(x-5)^2=32$، ومنه $x=5\\pm\\sqrt{32}$.","بإكمال المربع $x=\\frac{5\\pm\\sqrt{53}}2$، وبالرسم تقريباً −1.14 و6.14؛ لا توجد عوامل خطية نسبية.","بالتحليل $(x-7)(x+1)=0$، فالحلان 7 و−1.","لا توجد حلول حقيقية لأن التحليل بعوامل صحيحة غير ممكن."],"sourcePage":730,"sourceQuestion":39,"problemData":{"kind":"compare-strategies","coefficients":[1,-5,-7],"discriminant":53},"sourceKind":"reasoning","correctIndex":1}$question_json$::jsonb,revision=revision+1,updated_at=now() WHERE id='10g3-w9-p730-q39' AND NOT deleted AND data=$question_json${"id":"10g3-w9-p730-q39","classroom":"10G3","examWeek":9,"position":7,"type":"FRQ","exam":"EOT · 10G3 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 730 · Q39 · Quadratic reasoning · الاستدلال التربيعي","prompt":"Compare and contrast completing the square, graphing, and factoring for solving $x^2-5x-7=0$. Use completing the square to give exact solutions, state approximate graph intercepts, and discuss whether simple rational factoring is possible.","promptAr":"قارن بين إكمال المربع والرسم البياني والتحليل لحل $x^2-5x-7=0$. أعطِ الحلول الدقيقة بإكمال المربع، والتقاطعات التقريبية من الرسم، وناقش إمكان التحليل البسيط بمعاملات نسبية.","answer":"Completing the square: $x^2-5x=7$, then $x^2-5x+\\frac{25}{4}=\\frac{53}{4}$, so $(x-\\frac52)^2=\\frac{53}{4}$. Thus $x=\\frac{5\\pm\\sqrt{53}}2$. Graphing $y=x^2-5x-7$ gives approximate x-intercepts $(-1.14,0)$ and $(6.14,0)$. The discriminant is 53, not a rational square, so the polynomial does not factor into linear factors with rational coefficients. Real radical factors exist, but are less convenient to find directly. Completing the square is efficient for exact answers; graphing checks the approximate roots.","answerAr":"بإكمال المربع: $x^2-5x=7$، ثم $x^2-5x+\\frac{25}{4}=\\frac{53}{4}$، ولذلك $(x-\\frac52)^2=\\frac{53}{4}$. إذن $x=\\frac{5\\pm\\sqrt{53}}2$. يعطي رسم $y=x^2-5x-7$ التقاطعين التقريبيين $(-1.14,0)$ و$(6.14,0)$. المميز 53 ليس مربع عدد نسبي، فلا تتحلل كثيرة الحدود إلى عوامل خطية بمعاملات نسبية. يمكن كتابتها بعوامل جذرية حقيقية، لكن إيجادها مباشرة أقل سهولة. إكمال المربع مناسب للحلول الدقيقة، والرسم للتحقق التقريبي.","marks":5,"diagram":"none","difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":730,"sourceQuestion":39,"responseParts":[{"label":"Completing the square and exact roots · إكمال المربع والحلول الدقيقة"},{"label":"Graphing and factoring comparison · مقارنة الرسم والتحليل"}],"problemData":{"kind":"compare-strategies","coefficients":[1,-5,-7],"discriminant":53},"sourceKind":"reasoning"}$question_json$::jsonb;
UPDATE questions SET data=$question_json${"id":"10g3-w9-p725-q1-example","classroom":"10G3","examWeek":9,"position":8,"type":"MCQ","exam":"EOT · 10G3 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 725 · Example1 · Completing the square · إكمال المربع","prompt":"Which value of c and binomial square complete $x^2+8x+c$ correctly?","promptAr":"أي قيمة لـ c وصورة مربع ذي الحدين تكمل $x^2+8x+c$ بصورة صحيحة؟","answer":"Step 1: $8\\div2=4$. Step 2: $c=4^2=16$. Step 3: $x^2+8x+16=(x+4)^2$.","answerAr":"الخطوة ١: $8\\div2=4$. الخطوة ٢: $c=4^2=16$. الخطوة ٣: $x^2+8x+16=(x+4)^2$.","marks":1,"diagram":"none","difficulty":"Standard","image":"","options":["$c=16,\\quad (x-4)^2$","$c=4,\\quad (x+2)^2$","$c=16,\\quad (x+4)^2$","$c=64,\\quad (x+8)^2$"],"optionsAr":["$c=16,\\quad (x-4)^2$","$c=4,\\quad (x+2)^2$","$c=16,\\quad (x+4)^2$","$c=64,\\quad (x+8)^2$"],"sourcePage":725,"sourceQuestion":1,"sourcePart":"Example 1","expectedValues":{"half":4,"c":16},"problemData":{"kind":"complete-square","b":8,"c":16,"shift":4},"sourceKind":"worked-example","squareChoices":[[16,-4],[4,2],[16,4],[64,8]],"correctIndex":2}$question_json$::jsonb,revision=revision+1,updated_at=now() WHERE id='10g3-w9-p725-q1-example' AND NOT deleted AND data=$question_json${"id":"10g3-w9-p725-q1-example","classroom":"10G3","examWeek":9,"position":8,"type":"FRQ","exam":"EOT · 10G3 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 725 · Example1 · Completing the square · إكمال المربع","prompt":"Completing-the-square algorithm for $x^2+bx$: halve b, square the result, then add it. The rule is $x^2+bx+(\\frac b2)^2=(x+\\frac b2)^2$.\nFind c so that $x^2+8x+c$ is a perfect-square trinomial. Show half of 8, the value of c, and the resulting binomial square.","promptAr":"خوارزمية إكمال المربع للعبارة $x^2+bx$: خذ نصف b، ثم ربّعه، ثم أضف الناتج. القاعدة $x^2+bx+(\\frac b2)^2=(x+\\frac b2)^2$.\nأوجد c لكي تكون $x^2+8x+c$ ثلاثية حدود تمثل مربعاً كاملاً. اكتب نصف 8 وقيمة c وصورة مربع ذي الحدين.","answer":"Step 1: $8\\div2=4$. Step 2: $c=4^2=16$. Step 3: $x^2+8x+16=(x+4)^2$.","answerAr":"الخطوة ١: $8\\div2=4$. الخطوة ٢: $c=4^2=16$. الخطوة ٣: $x^2+8x+16=(x+4)^2$.","marks":3,"diagram":"none","difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":725,"sourceQuestion":1,"sourcePart":"Example 1","responseParts":[{"label":"Half of b · نصف معامل x"},{"label":"Value of c · قيمة c"},{"label":"Perfect-square form · صورة المربع الكامل"}],"expectedValues":{"half":4,"c":16},"problemData":{"kind":"complete-square","b":8,"c":16,"shift":4},"sourceKind":"worked-example"}$question_json$::jsonb;
UPDATE questions SET data=$question_json${"id":"10g3-w9-p729-q1","classroom":"10G3","examWeek":9,"position":9,"type":"MCQ","exam":"EOT · 10G3 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 729 · Q1 · Completing the square · إكمال المربع","prompt":"Which value of c and binomial square complete $x^2+26x+c$ correctly?","promptAr":"أي قيمة لـ c وصورة مربع ذي الحدين تكمل $x^2+26x+c$ بصورة صحيحة؟","answer":"$c=(\\frac{26}{2})^2=169$. Hence $x^2+26x+169=(x+13)^2$.","answerAr":"$c=(\\frac{26}{2})^2=169$. ومنه $x^2+26x+169=(x+13)^2$.","marks":1,"diagram":"none","difficulty":"Standard","image":"","options":["$c=676,\\quad (x+26)^2$","$c=169,\\quad (x-13)^2$","$c=42.25,\\quad (x+6.5)^2$","$c=169,\\quad (x+13)^2$"],"optionsAr":["$c=676,\\quad (x+26)^2$","$c=169,\\quad (x-13)^2$","$c=42.25,\\quad (x+6.5)^2$","$c=169,\\quad (x+13)^2$"],"sourcePage":729,"sourceQuestion":1,"expectedValues":{"c":169},"problemData":{"kind":"complete-square","b":26,"c":169,"shift":13},"squareChoices":[[676,26],[169,-13],[42.25,6.5],[169,13]],"correctIndex":3}$question_json$::jsonb,revision=revision+1,updated_at=now() WHERE id='10g3-w9-p729-q1' AND NOT deleted AND data=$question_json${"id":"10g3-w9-p729-q1","classroom":"10G3","examWeek":9,"position":9,"type":"FRQ","exam":"EOT · 10G3 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 729 · Q1 · Completing the square · إكمال المربع","prompt":"Find c so that $x^2+26x+c$ is a perfect-square trinomial. Verify by writing it as a binomial square.","promptAr":"أوجد c لكي تكون $x^2+26x+c$ ثلاثية حدود تمثل مربعاً كاملاً. تحقق بكتابتها في صورة مربع ذي حدين.","answer":"$c=(\\frac{26}{2})^2=169$. Hence $x^2+26x+169=(x+13)^2$.","answerAr":"$c=(\\frac{26}{2})^2=169$. ومنه $x^2+26x+169=(x+13)^2$.","marks":2,"diagram":"none","difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":729,"sourceQuestion":1,"responseParts":[{"label":"Value of c · قيمة c"},{"label":"Perfect-square form / check · صورة المربع والتحقق"}],"expectedValues":{"c":169},"problemData":{"kind":"complete-square","b":26,"c":169,"shift":13}}$question_json$::jsonb;
UPDATE questions SET data=$question_json${"id":"10g3-w9-p729-q2","classroom":"10G3","examWeek":9,"position":10,"type":"MCQ","exam":"EOT · 10G3 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 729 · Q2 · Completing the square · إكمال المربع","prompt":"Which value of c and binomial square complete $x^2-24x+c$ correctly?","promptAr":"أي قيمة لـ c وصورة مربع ذي الحدين تكمل $x^2-24x+c$ بصورة صحيحة؟","answer":"$c=(\\frac{-24}{2})^2=144$. Hence $x^2-24x+144=(x-12)^2$.","answerAr":"$c=(\\frac{-24}{2})^2=144$. ومنه $x^2-24x+144=(x-12)^2$.","marks":1,"diagram":"none","difficulty":"Standard","image":"","options":["$c=144,\\quad (x-12)^2$","$c=576,\\quad (x-24)^2$","$c=144,\\quad (x+12)^2$","$c=36,\\quad (x-6)^2$"],"optionsAr":["$c=144,\\quad (x-12)^2$","$c=576,\\quad (x-24)^2$","$c=144,\\quad (x+12)^2$","$c=36,\\quad (x-6)^2$"],"sourcePage":729,"sourceQuestion":2,"expectedValues":{"c":144},"problemData":{"kind":"complete-square","b":-24,"c":144,"shift":-12},"squareChoices":[[144,-12],[576,-24],[144,12],[36,-6]],"correctIndex":0}$question_json$::jsonb,revision=revision+1,updated_at=now() WHERE id='10g3-w9-p729-q2' AND NOT deleted AND data=$question_json${"id":"10g3-w9-p729-q2","classroom":"10G3","examWeek":9,"position":10,"type":"FRQ","exam":"EOT · 10G3 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 729 · Q2 · Completing the square · إكمال المربع","prompt":"Find c so that $x^2-24x+c$ is a perfect-square trinomial. Verify by writing it as a binomial square.","promptAr":"أوجد c لكي تكون $x^2-24x+c$ ثلاثية حدود تمثل مربعاً كاملاً. تحقق بكتابتها في صورة مربع ذي حدين.","answer":"$c=(\\frac{-24}{2})^2=144$. Hence $x^2-24x+144=(x-12)^2$.","answerAr":"$c=(\\frac{-24}{2})^2=144$. ومنه $x^2-24x+144=(x-12)^2$.","marks":2,"diagram":"none","difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":729,"sourceQuestion":2,"responseParts":[{"label":"Value of c · قيمة c"},{"label":"Perfect-square form / check · صورة المربع والتحقق"}],"expectedValues":{"c":144},"problemData":{"kind":"complete-square","b":-24,"c":144,"shift":-12}}$question_json$::jsonb;
UPDATE questions SET data=$question_json${"id":"10g3-w9-p729-q3","classroom":"10G3","examWeek":9,"position":11,"type":"MCQ","exam":"EOT · 10G3 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 729 · Q3 · Completing the square · إكمال المربع","prompt":"Which value of c and binomial square complete $x^2-19x+c$ correctly?","promptAr":"أي قيمة لـ c وصورة مربع ذي الحدين تكمل $x^2-19x+c$ بصورة صحيحة؟","answer":"$c=(\\frac{-19}{2})^2=\\frac{361}{4}=90.25$. Hence $x^2-19x+\\frac{361}{4}=(x-\\frac{19}{2})^2$.","answerAr":"$c=(\\frac{-19}{2})^2=\\frac{361}{4}=90.25$. ومنه $x^2-19x+\\frac{361}{4}=(x-\\frac{19}{2})^2$.","marks":1,"diagram":"none","difficulty":"Standard","image":"","options":["$c=22.5625,\\quad (x-4.75)^2$","$c=90.25,\\quad (x-9.5)^2$","$c=361,\\quad (x-19)^2$","$c=90.25,\\quad (x+9.5)^2$"],"optionsAr":["$c=22.5625,\\quad (x-4.75)^2$","$c=90.25,\\quad (x-9.5)^2$","$c=361,\\quad (x-19)^2$","$c=90.25,\\quad (x+9.5)^2$"],"sourcePage":729,"sourceQuestion":3,"expectedValues":{"c":90.25},"problemData":{"kind":"complete-square","b":-19,"c":90.25,"shift":-9.5},"squareChoices":[[22.5625,-4.75],[90.25,-9.5],[361,-19],[90.25,9.5]],"correctIndex":1}$question_json$::jsonb,revision=revision+1,updated_at=now() WHERE id='10g3-w9-p729-q3' AND NOT deleted AND data=$question_json${"id":"10g3-w9-p729-q3","classroom":"10G3","examWeek":9,"position":11,"type":"FRQ","exam":"EOT · 10G3 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 729 · Q3 · Completing the square · إكمال المربع","prompt":"Find c so that $x^2-19x+c$ is a perfect-square trinomial. Verify by writing it as a binomial square.","promptAr":"أوجد c لكي تكون $x^2-19x+c$ ثلاثية حدود تمثل مربعاً كاملاً. تحقق بكتابتها في صورة مربع ذي حدين.","answer":"$c=(\\frac{-19}{2})^2=\\frac{361}{4}=90.25$. Hence $x^2-19x+\\frac{361}{4}=(x-\\frac{19}{2})^2$.","answerAr":"$c=(\\frac{-19}{2})^2=\\frac{361}{4}=90.25$. ومنه $x^2-19x+\\frac{361}{4}=(x-\\frac{19}{2})^2$.","marks":2,"diagram":"none","difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":729,"sourceQuestion":3,"responseParts":[{"label":"Value of c · قيمة c"},{"label":"Perfect-square form / check · صورة المربع والتحقق"}],"expectedValues":{"c":90.25},"problemData":{"kind":"complete-square","b":-19,"c":90.25,"shift":-9.5}}$question_json$::jsonb;
UPDATE questions SET data=$question_json${"id":"10g3-w9-p729-q4","classroom":"10G3","examWeek":9,"position":12,"type":"MCQ","exam":"EOT · 10G3 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 729 · Q4 · Completing the square · إكمال المربع","prompt":"Which value of c and binomial square complete $x^2+17x+c$ correctly?","promptAr":"أي قيمة لـ c وصورة مربع ذي الحدين تكمل $x^2+17x+c$ بصورة صحيحة؟","answer":"$c=(\\frac{17}{2})^2=\\frac{289}{4}=72.25$. Hence $x^2+17x+\\frac{289}{4}=(x+\\frac{17}{2})^2$.","answerAr":"$c=(\\frac{17}{2})^2=\\frac{289}{4}=72.25$. ومنه $x^2+17x+\\frac{289}{4}=(x+\\frac{17}{2})^2$.","marks":1,"diagram":"none","difficulty":"Standard","image":"","options":["$c=72.25,\\quad (x-8.5)^2$","$c=18.0625,\\quad (x+4.25)^2$","$c=72.25,\\quad (x+8.5)^2$","$c=289,\\quad (x+17)^2$"],"optionsAr":["$c=72.25,\\quad (x-8.5)^2$","$c=18.0625,\\quad (x+4.25)^2$","$c=72.25,\\quad (x+8.5)^2$","$c=289,\\quad (x+17)^2$"],"sourcePage":729,"sourceQuestion":4,"expectedValues":{"c":72.25},"problemData":{"kind":"complete-square","b":17,"c":72.25,"shift":8.5},"squareChoices":[[72.25,-8.5],[18.0625,4.25],[72.25,8.5],[289,17]],"correctIndex":2}$question_json$::jsonb,revision=revision+1,updated_at=now() WHERE id='10g3-w9-p729-q4' AND NOT deleted AND data=$question_json${"id":"10g3-w9-p729-q4","classroom":"10G3","examWeek":9,"position":12,"type":"FRQ","exam":"EOT · 10G3 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 729 · Q4 · Completing the square · إكمال المربع","prompt":"Find c so that $x^2+17x+c$ is a perfect-square trinomial. Verify by writing it as a binomial square.","promptAr":"أوجد c لكي تكون $x^2+17x+c$ ثلاثية حدود تمثل مربعاً كاملاً. تحقق بكتابتها في صورة مربع ذي حدين.","answer":"$c=(\\frac{17}{2})^2=\\frac{289}{4}=72.25$. Hence $x^2+17x+\\frac{289}{4}=(x+\\frac{17}{2})^2$.","answerAr":"$c=(\\frac{17}{2})^2=\\frac{289}{4}=72.25$. ومنه $x^2+17x+\\frac{289}{4}=(x+\\frac{17}{2})^2$.","marks":2,"diagram":"none","difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":729,"sourceQuestion":4,"responseParts":[{"label":"Value of c · قيمة c"},{"label":"Perfect-square form / check · صورة المربع والتحقق"}],"expectedValues":{"c":72.25},"problemData":{"kind":"complete-square","b":17,"c":72.25,"shift":8.5}}$question_json$::jsonb;
UPDATE questions SET data=$question_json${"id":"10g3-w9-p729-q5","classroom":"10G3","examWeek":9,"position":13,"type":"MCQ","exam":"EOT · 10G3 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 729 · Q5 · Completing the square · إكمال المربع","prompt":"Which value of c and binomial square complete $x^2+5x+c$ correctly?","promptAr":"أي قيمة لـ c وصورة مربع ذي الحدين تكمل $x^2+5x+c$ بصورة صحيحة؟","answer":"$c=(\\frac{5}{2})^2=\\frac{25}{4}=6.25$. Hence $x^2+5x+\\frac{25}{4}=(x+\\frac{5}{2})^2$.","answerAr":"$c=(\\frac{5}{2})^2=\\frac{25}{4}=6.25$. ومنه $x^2+5x+\\frac{25}{4}=(x+\\frac{5}{2})^2$.","marks":1,"diagram":"none","difficulty":"Standard","image":"","options":["$c=25,\\quad (x+5)^2$","$c=6.25,\\quad (x-2.5)^2$","$c=1.5625,\\quad (x+1.25)^2$","$c=6.25,\\quad (x+2.5)^2$"],"optionsAr":["$c=25,\\quad (x+5)^2$","$c=6.25,\\quad (x-2.5)^2$","$c=1.5625,\\quad (x+1.25)^2$","$c=6.25,\\quad (x+2.5)^2$"],"sourcePage":729,"sourceQuestion":5,"expectedValues":{"c":6.25},"problemData":{"kind":"complete-square","b":5,"c":6.25,"shift":2.5},"squareChoices":[[25,5],[6.25,-2.5],[1.5625,1.25],[6.25,2.5]],"correctIndex":3}$question_json$::jsonb,revision=revision+1,updated_at=now() WHERE id='10g3-w9-p729-q5' AND NOT deleted AND data=$question_json${"id":"10g3-w9-p729-q5","classroom":"10G3","examWeek":9,"position":13,"type":"FRQ","exam":"EOT · 10G3 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 729 · Q5 · Completing the square · إكمال المربع","prompt":"Find c so that $x^2+5x+c$ is a perfect-square trinomial. Verify by writing it as a binomial square.","promptAr":"أوجد c لكي تكون $x^2+5x+c$ ثلاثية حدود تمثل مربعاً كاملاً. تحقق بكتابتها في صورة مربع ذي حدين.","answer":"$c=(\\frac{5}{2})^2=\\frac{25}{4}=6.25$. Hence $x^2+5x+\\frac{25}{4}=(x+\\frac{5}{2})^2$.","answerAr":"$c=(\\frac{5}{2})^2=\\frac{25}{4}=6.25$. ومنه $x^2+5x+\\frac{25}{4}=(x+\\frac{5}{2})^2$.","marks":2,"diagram":"none","difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":729,"sourceQuestion":5,"responseParts":[{"label":"Value of c · قيمة c"},{"label":"Perfect-square form / check · صورة المربع والتحقق"}],"expectedValues":{"c":6.25},"problemData":{"kind":"complete-square","b":5,"c":6.25,"shift":2.5}}$question_json$::jsonb;
UPDATE questions SET data=$question_json${"id":"10g3-w9-p729-q6","classroom":"10G3","examWeek":9,"position":14,"type":"MCQ","exam":"EOT · 10G3 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 729 · Q6 · Completing the square · إكمال المربع","prompt":"Which value of c and binomial square complete $x^2-13x+c$ correctly?","promptAr":"أي قيمة لـ c وصورة مربع ذي الحدين تكمل $x^2-13x+c$ بصورة صحيحة؟","answer":"$c=(\\frac{-13}{2})^2=\\frac{169}{4}=42.25$. Hence $x^2-13x+\\frac{169}{4}=(x-\\frac{13}{2})^2$.","answerAr":"$c=(\\frac{-13}{2})^2=\\frac{169}{4}=42.25$. ومنه $x^2-13x+\\frac{169}{4}=(x-\\frac{13}{2})^2$.","marks":1,"diagram":"none","difficulty":"Standard","image":"","options":["$c=42.25,\\quad (x-6.5)^2$","$c=169,\\quad (x-13)^2$","$c=42.25,\\quad (x+6.5)^2$","$c=10.5625,\\quad (x-3.25)^2$"],"optionsAr":["$c=42.25,\\quad (x-6.5)^2$","$c=169,\\quad (x-13)^2$","$c=42.25,\\quad (x+6.5)^2$","$c=10.5625,\\quad (x-3.25)^2$"],"sourcePage":729,"sourceQuestion":6,"expectedValues":{"c":42.25},"problemData":{"kind":"complete-square","b":-13,"c":42.25,"shift":-6.5},"squareChoices":[[42.25,-6.5],[169,-13],[42.25,6.5],[10.5625,-3.25]],"correctIndex":0}$question_json$::jsonb,revision=revision+1,updated_at=now() WHERE id='10g3-w9-p729-q6' AND NOT deleted AND data=$question_json${"id":"10g3-w9-p729-q6","classroom":"10G3","examWeek":9,"position":14,"type":"FRQ","exam":"EOT · 10G3 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 729 · Q6 · Completing the square · إكمال المربع","prompt":"Find c so that $x^2-13x+c$ is a perfect-square trinomial. Verify by writing it as a binomial square.","promptAr":"أوجد c لكي تكون $x^2-13x+c$ ثلاثية حدود تمثل مربعاً كاملاً. تحقق بكتابتها في صورة مربع ذي حدين.","answer":"$c=(\\frac{-13}{2})^2=\\frac{169}{4}=42.25$. Hence $x^2-13x+\\frac{169}{4}=(x-\\frac{13}{2})^2$.","answerAr":"$c=(\\frac{-13}{2})^2=\\frac{169}{4}=42.25$. ومنه $x^2-13x+\\frac{169}{4}=(x-\\frac{13}{2})^2$.","marks":2,"diagram":"none","difficulty":"Standard","image":"","options":[],"optionsAr":[],"sourcePage":729,"sourceQuestion":6,"responseParts":[{"label":"Value of c · قيمة c"},{"label":"Perfect-square form / check · صورة المربع والتحقق"}],"expectedValues":{"c":42.25},"problemData":{"kind":"complete-square","b":-13,"c":42.25,"shift":-6.5}}$question_json$::jsonb;
INSERT INTO questions(id,data) VALUES
('10g3-w9-p722-q29-a',$question_json${"id":"10g3-w9-p722-q29-a","classroom":"10G3","examWeek":9,"position":1,"type":"MCQ","exam":"EOT · 10G3 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 722 · Q29A · Quadratic applications · تطبيقات تربيعية","prompt":"A freely falling ballast bag is accidentally dropped from a hot-air balloon 576 feet above the ground. Its height in feet after t seconds is $f(t)=-16t^2+576$, with $t\\ge0$. After how many seconds does the bag hit the ground?","promptAr":"سقط كيس أثقال سقوطاً حراً من منطاد على ارتفاع 576 قدماً عن الأرض. ارتفاعه بالأقدام بعد t ثانية هو $f(t)=-16t^2+576$، حيث $t\\ge0$. بعد كم ثانية يصل الكيس إلى الأرض؟","answer":"The ground is at $f(t)=0$. $-16t^2+576=0$ gives $t^2=36$, so $t=\\pm6$. Time must be nonnegative, so $t=6$ seconds (option B).","answerAr":"عند الأرض $f(t)=0$. من $-16t^2+576=0$ نحصل على $t^2=36$، ومنه $t=\\pm6$. الزمن غير سالب، لذلك $t=6$ ثوانٍ (الخيار B).","marks":1,"diagram":"none","difficulty":"Standard","image":"","options":["−6 seconds","6 seconds","36 seconds","144 seconds"],"optionsAr":["−6 ثوانٍ","6 ثوانٍ","36 ثانية","144 ثانية"],"sourcePage":722,"sourceQuestion":29,"sourcePart":"A","correctIndex":1,"expectedValues":{"t":6},"sourceKind":"application"}$question_json$::jsonb),
('10g3-w9-p722-q29-b',$question_json${"id":"10g3-w9-p722-q29-b","classroom":"10G3","examWeek":9,"position":2,"type":"MCQ","exam":"EOT · 10G3 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 722 · Q29B · Quadratic applications · تطبيقات تربيعية","prompt":"A freely falling ballast bag is accidentally dropped from a hot-air balloon 576 feet above the ground. Its height in feet after t seconds is $f(t)=-16t^2+576$, with $t\\ge0$. Which equation is obtained by correctly factoring the height polynomial and setting it equal to zero?","promptAr":"سقط كيس أثقال سقوطاً حراً من منطاد على ارتفاع 576 قدماً عن الأرض. ارتفاعه بالأقدام بعد t ثانية هو $f(t)=-16t^2+576$، حيث $t\\ge0$. أي معادلة تنتج عن التحليل الجبري الصحيح لكثيرة حدود الارتفاع ثم مساواتها بالصفر؟","answer":"$-16t^2+576=-16(t^2-36)=-16(t-6)(t+6)$. Therefore the factored equation is $-16(t-6)(t+6)=0$ (option A).","answerAr":"$-16t^2+576=-16(t^2-36)=-16(t-6)(t+6)$. إذن الصورة المحللة $-16(t-6)(t+6)=0$ (الخيار A).","marks":1,"diagram":"none","difficulty":"Standard","image":"","options":["$-16(t-6)(t+6)=0$","$-16(t-36)(t+36)=0$","$-16(t-6)^2=0$","$-16(t^2+36)=0$"],"optionsAr":["$-16(t-6)(t+6)=0$","$-16(t-36)(t+36)=0$","$-16(t-6)^2=0$","$-16(t^2+36)=0$"],"sourcePage":722,"sourceQuestion":29,"sourcePart":"B","correctIndex":0,"problemData":{"kind":"factor-equation","coefficients":[-16,0,576],"optionCoefficients":[[-16,0,576],[-16,0,20736],[-16,192,-576],[-16,0,-576]]},"sourceKind":"application"}$question_json$::jsonb),
('10g3-w9-p722-q30-a',$question_json${"id":"10g3-w9-p722-q30-a","classroom":"10G3","examWeek":9,"position":3,"type":"MCQ","exam":"EOT · 10G3 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 722 · Q30A · Quadratic applications · تطبيقات تربيعية","prompt":"Catalina cuts 3-inch squares from the corners of a square sheet of cardboard and folds the sides to make an open-topped box. Its volume is $V=3x^2-36x+108$, where x is the original side length in inches and $x>6$. Which expression is the completely factored form of the volume polynomial?","promptAr":"تقص كاتالينا مربعات طول ضلعها 3 بوصات من زوايا قطعة كرتون مربعة، ثم تطوي الجوانب لتكوين صندوق مفتوح. حجمه $V=3x^2-36x+108$، حيث x طول ضلع الكرتون الأصلي بالبوصات و$x>6$. أي عبارة تمثل التحليل الكامل لكثيرة حدود الحجم؟","answer":"$3x^2-36x+108=3(x^2-12x+36)=3(x-6)^2$ (option A). The base has side length $x-6$ and the height is 3 inches.","answerAr":"$3x^2-36x+108=3(x^2-12x+36)=3(x-6)^2$ (الخيار A). طول ضلع القاعدة $x-6$ والارتفاع 3 بوصات.","marks":1,"diagram":"box-net","difficulty":"Standard","image":"","options":["$3(x-6)^2$","$3(x+6)^2$","$(3x-6)^2$","$3(x-3)(x-12)$"],"optionsAr":["$3(x-6)^2$","$3(x+6)^2$","$(3x-6)^2$","$3(x-3)(x-12)$"],"sourcePage":722,"sourceQuestion":30,"sourcePart":"A","correctIndex":0,"problemData":{"kind":"factor-polynomial","coefficients":[3,-36,108],"optionCoefficients":[[3,-36,108],[3,36,108],[9,-36,36],[3,-45,108]]},"sourceKind":"application"}$question_json$::jsonb),
('10g3-w9-p722-q30-b',$question_json${"id":"10g3-w9-p722-q30-b","classroom":"10G3","examWeek":9,"position":4,"type":"MCQ","exam":"EOT · 10G3 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 722 · Q30B · Quadratic applications · تطبيقات تربيعية","prompt":"Catalina cuts 3-inch squares from the corners of a square sheet of cardboard and folds the sides to make an open-topped box. Its volume is $V=3x^2-36x+108$, where x is the original side length in inches and $x>6$. What is the volume when the original cardboard has side length 9 inches?","promptAr":"تقص كاتالينا مربعات طول ضلعها 3 بوصات من زوايا قطعة كرتون مربعة، ثم تطوي الجوانب لتكوين صندوق مفتوح. حجمه $V=3x^2-36x+108$، حيث x طول ضلع الكرتون الأصلي بالبوصات و$x>6$. ما حجم الصندوق عندما يكون طول ضلع الكرتون الأصلي 9 بوصات؟","answer":"Substitute $x=9$: $V=3(9-6)^2=3(3)^2=27$ cubic inches (option C).","answerAr":"نعوض $x=9$: $V=3(9-6)^2=3(3)^2=27$ بوصة مكعبة (الخيار C).","marks":1,"diagram":"box-net","difficulty":"Standard","image":"","options":["$9\\text{ in}^3$","$18\\text{ in}^3$","$27\\text{ in}^3$","$81\\text{ in}^3$"],"optionsAr":["9 بوصات مكعبة","18 بوصة مكعبة","27 بوصة مكعبة","81 بوصة مكعبة"],"sourcePage":722,"sourceQuestion":30,"sourcePart":"B","correctIndex":2,"expectedValues":{"V":27},"problemData":{"kind":"volume","x":9,"height":3,"cut":3},"sourceKind":"application"}$question_json$::jsonb),
('10g3-w9-p730-q37',$question_json${"id":"10g3-w9-p730-q37","classroom":"10G3","examWeek":9,"position":5,"type":"MCQ","exam":"EOT · 10G3 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 730 · Q37 · Quadratic reasoning · الاستدلال التربيعي","prompt":"Which expression is not a perfect-square trinomial?","promptAr":"أي عبارة ليست ثلاثية حدود تمثل مربعاً كاملاً؟","answer":"D does not belong. A $=(n-\\frac12)^2$, B $=(n+\\frac12)^2$, and C $=(n-\\frac13)^2$. In D, half the linear coefficient is $\\frac16$, whose square is $\\frac1{36}$, not $\\frac19$. Therefore D is not a perfect-square trinomial.","answerAr":"العبارة D لا تنتمي. فالعبارة A تساوي $(n-\\frac12)^2$، وB تساوي $(n+\\frac12)^2$، وC تساوي $(n-\\frac13)^2$. في D نصف معامل n هو $\\frac16$ ومربعه $\\frac1{36}$ وليس $\\frac19$؛ لذا ليست مربعاً كاملاً.","marks":1,"diagram":"none","difficulty":"Standard","image":"","options":["$n^2-n+\\frac14$","$n^2+n+\\frac14$","$n^2-\\frac23n+\\frac19$","$n^2+\\frac13n+\\frac19$"],"optionsAr":["$n^2-n+\\frac14$","$n^2+n+\\frac14$","$n^2-\\frac23n+\\frac19$","$n^2+\\frac13n+\\frac19$"],"sourcePage":730,"sourceQuestion":37,"problemData":{"kind":"odd-one-out","coefficients":[[1,-1,0.25],[1,1,0.25],[1,-0.6666666666666666,0.1111111111111111],[1,0.3333333333333333,0.1111111111111111]],"oddIndex":3},"sourceKind":"reasoning","correctIndex":3}$question_json$::jsonb),
('10g3-w9-p730-q38',$question_json${"id":"10g3-w9-p730-q38","classroom":"10G3","examWeek":9,"position":6,"type":"MCQ","exam":"EOT · 10G3 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 730 · Q38 · Quadratic reasoning · الاستدلال التربيعي","prompt":"Which quadratic equation has 4 as its only solution?","promptAr":"أي معادلة تربيعية حلها الوحيد هو 4؟","answer":"One example is $(x-4)^2=0$, or $x^2-8x+16=0$. Taking square roots gives $x-4=0$, hence $x=4$, a repeated root. Any equation $a(x-4)^2=0$ with $a\\ne0$ is acceptable.","answerAr":"مثال صحيح: $(x-4)^2=0$، أي $x^2-8x+16=0$. بأخذ الجذر التربيعي نحصل على $x-4=0$، ومنه $x=4$ وهو جذر مكرر. تُقبل أي معادلة $a(x-4)^2=0$ حيث $a\\ne0$.","marks":1,"diagram":"none","difficulty":"Standard","image":"","options":["$(x-4)^2=0$","$(x+4)^2=0$","$x^2-16=0$","$x^2+16=0$"],"optionsAr":["$(x-4)^2=0$","$(x+4)^2=0$","$x^2-16=0$","$x^2+16=0$"],"sourcePage":730,"sourceQuestion":38,"expectedValues":{"root":4},"problemData":{"kind":"create-equation","exampleCoefficients":[1,-8,16]},"sourceKind":"reasoning","correctIndex":0}$question_json$::jsonb),
('10g3-w9-p730-q39',$question_json${"id":"10g3-w9-p730-q39","classroom":"10G3","examWeek":9,"position":7,"type":"MCQ","exam":"EOT · 10G3 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 730 · Q39 · Quadratic reasoning · الاستدلال التربيعي","prompt":"Which comparison is correct for solving $x^2-5x-7=0$?","promptAr":"أي مقارنة صحيحة لحل $x^2-5x-7=0$؟","answer":"Completing the square: $x^2-5x=7$, then $x^2-5x+\\frac{25}{4}=\\frac{53}{4}$, so $(x-\\frac52)^2=\\frac{53}{4}$. Thus $x=\\frac{5\\pm\\sqrt{53}}2$. Graphing $y=x^2-5x-7$ gives approximate x-intercepts $(-1.14,0)$ and $(6.14,0)$. The discriminant is 53, not a rational square, so the polynomial does not factor into linear factors with rational coefficients. Real radical factors exist, but are less convenient to find directly. Completing the square is efficient for exact answers; graphing checks the approximate roots.","answerAr":"بإكمال المربع: $x^2-5x=7$، ثم $x^2-5x+\\frac{25}{4}=\\frac{53}{4}$، ولذلك $(x-\\frac52)^2=\\frac{53}{4}$. إذن $x=\\frac{5\\pm\\sqrt{53}}2$. يعطي رسم $y=x^2-5x-7$ التقاطعين التقريبيين $(-1.14,0)$ و$(6.14,0)$. المميز 53 ليس مربع عدد نسبي، فلا تتحلل كثيرة الحدود إلى عوامل خطية بمعاملات نسبية. يمكن كتابتها بعوامل جذرية حقيقية، لكن إيجادها مباشرة أقل سهولة. إكمال المربع مناسب للحلول الدقيقة، والرسم للتحقق التقريبي.","marks":1,"diagram":"none","difficulty":"Standard","image":"","options":["Completing the square gives $(x-5)^2=32$, so $x=5\\pm\\sqrt{32}$.","Completing the square gives $x=\\frac{5\\pm\\sqrt{53}}2$; graphing gives approximately −1.14 and 6.14; no rational linear factors.","Factoring gives $(x-7)(x+1)=0$, so the solutions are 7 and −1.","There are no real solutions because integer factoring is impossible."],"optionsAr":["بإكمال المربع $(x-5)^2=32$، ومنه $x=5\\pm\\sqrt{32}$.","بإكمال المربع $x=\\frac{5\\pm\\sqrt{53}}2$، وبالرسم تقريباً −1.14 و6.14؛ لا توجد عوامل خطية نسبية.","بالتحليل $(x-7)(x+1)=0$، فالحلان 7 و−1.","لا توجد حلول حقيقية لأن التحليل بعوامل صحيحة غير ممكن."],"sourcePage":730,"sourceQuestion":39,"problemData":{"kind":"compare-strategies","coefficients":[1,-5,-7],"discriminant":53},"sourceKind":"reasoning","correctIndex":1}$question_json$::jsonb),
('10g3-w9-p725-q1-example',$question_json${"id":"10g3-w9-p725-q1-example","classroom":"10G3","examWeek":9,"position":8,"type":"MCQ","exam":"EOT · 10G3 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 725 · Example1 · Completing the square · إكمال المربع","prompt":"Which value of c and binomial square complete $x^2+8x+c$ correctly?","promptAr":"أي قيمة لـ c وصورة مربع ذي الحدين تكمل $x^2+8x+c$ بصورة صحيحة؟","answer":"Step 1: $8\\div2=4$. Step 2: $c=4^2=16$. Step 3: $x^2+8x+16=(x+4)^2$.","answerAr":"الخطوة ١: $8\\div2=4$. الخطوة ٢: $c=4^2=16$. الخطوة ٣: $x^2+8x+16=(x+4)^2$.","marks":1,"diagram":"none","difficulty":"Standard","image":"","options":["$c=16,\\quad (x-4)^2$","$c=4,\\quad (x+2)^2$","$c=16,\\quad (x+4)^2$","$c=64,\\quad (x+8)^2$"],"optionsAr":["$c=16,\\quad (x-4)^2$","$c=4,\\quad (x+2)^2$","$c=16,\\quad (x+4)^2$","$c=64,\\quad (x+8)^2$"],"sourcePage":725,"sourceQuestion":1,"sourcePart":"Example 1","expectedValues":{"half":4,"c":16},"problemData":{"kind":"complete-square","b":8,"c":16,"shift":4},"sourceKind":"worked-example","squareChoices":[[16,-4],[4,2],[16,4],[64,8]],"correctIndex":2}$question_json$::jsonb),
('10g3-w9-p729-q1',$question_json${"id":"10g3-w9-p729-q1","classroom":"10G3","examWeek":9,"position":9,"type":"MCQ","exam":"EOT · 10G3 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 729 · Q1 · Completing the square · إكمال المربع","prompt":"Which value of c and binomial square complete $x^2+26x+c$ correctly?","promptAr":"أي قيمة لـ c وصورة مربع ذي الحدين تكمل $x^2+26x+c$ بصورة صحيحة؟","answer":"$c=(\\frac{26}{2})^2=169$. Hence $x^2+26x+169=(x+13)^2$.","answerAr":"$c=(\\frac{26}{2})^2=169$. ومنه $x^2+26x+169=(x+13)^2$.","marks":1,"diagram":"none","difficulty":"Standard","image":"","options":["$c=676,\\quad (x+26)^2$","$c=169,\\quad (x-13)^2$","$c=42.25,\\quad (x+6.5)^2$","$c=169,\\quad (x+13)^2$"],"optionsAr":["$c=676,\\quad (x+26)^2$","$c=169,\\quad (x-13)^2$","$c=42.25,\\quad (x+6.5)^2$","$c=169,\\quad (x+13)^2$"],"sourcePage":729,"sourceQuestion":1,"expectedValues":{"c":169},"problemData":{"kind":"complete-square","b":26,"c":169,"shift":13},"squareChoices":[[676,26],[169,-13],[42.25,6.5],[169,13]],"correctIndex":3}$question_json$::jsonb),
('10g3-w9-p729-q2',$question_json${"id":"10g3-w9-p729-q2","classroom":"10G3","examWeek":9,"position":10,"type":"MCQ","exam":"EOT · 10G3 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 729 · Q2 · Completing the square · إكمال المربع","prompt":"Which value of c and binomial square complete $x^2-24x+c$ correctly?","promptAr":"أي قيمة لـ c وصورة مربع ذي الحدين تكمل $x^2-24x+c$ بصورة صحيحة؟","answer":"$c=(\\frac{-24}{2})^2=144$. Hence $x^2-24x+144=(x-12)^2$.","answerAr":"$c=(\\frac{-24}{2})^2=144$. ومنه $x^2-24x+144=(x-12)^2$.","marks":1,"diagram":"none","difficulty":"Standard","image":"","options":["$c=144,\\quad (x-12)^2$","$c=576,\\quad (x-24)^2$","$c=144,\\quad (x+12)^2$","$c=36,\\quad (x-6)^2$"],"optionsAr":["$c=144,\\quad (x-12)^2$","$c=576,\\quad (x-24)^2$","$c=144,\\quad (x+12)^2$","$c=36,\\quad (x-6)^2$"],"sourcePage":729,"sourceQuestion":2,"expectedValues":{"c":144},"problemData":{"kind":"complete-square","b":-24,"c":144,"shift":-12},"squareChoices":[[144,-12],[576,-24],[144,12],[36,-6]],"correctIndex":0}$question_json$::jsonb),
('10g3-w9-p729-q3',$question_json${"id":"10g3-w9-p729-q3","classroom":"10G3","examWeek":9,"position":11,"type":"MCQ","exam":"EOT · 10G3 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 729 · Q3 · Completing the square · إكمال المربع","prompt":"Which value of c and binomial square complete $x^2-19x+c$ correctly?","promptAr":"أي قيمة لـ c وصورة مربع ذي الحدين تكمل $x^2-19x+c$ بصورة صحيحة؟","answer":"$c=(\\frac{-19}{2})^2=\\frac{361}{4}=90.25$. Hence $x^2-19x+\\frac{361}{4}=(x-\\frac{19}{2})^2$.","answerAr":"$c=(\\frac{-19}{2})^2=\\frac{361}{4}=90.25$. ومنه $x^2-19x+\\frac{361}{4}=(x-\\frac{19}{2})^2$.","marks":1,"diagram":"none","difficulty":"Standard","image":"","options":["$c=22.5625,\\quad (x-4.75)^2$","$c=90.25,\\quad (x-9.5)^2$","$c=361,\\quad (x-19)^2$","$c=90.25,\\quad (x+9.5)^2$"],"optionsAr":["$c=22.5625,\\quad (x-4.75)^2$","$c=90.25,\\quad (x-9.5)^2$","$c=361,\\quad (x-19)^2$","$c=90.25,\\quad (x+9.5)^2$"],"sourcePage":729,"sourceQuestion":3,"expectedValues":{"c":90.25},"problemData":{"kind":"complete-square","b":-19,"c":90.25,"shift":-9.5},"squareChoices":[[22.5625,-4.75],[90.25,-9.5],[361,-19],[90.25,9.5]],"correctIndex":1}$question_json$::jsonb),
('10g3-w9-p729-q4',$question_json${"id":"10g3-w9-p729-q4","classroom":"10G3","examWeek":9,"position":12,"type":"MCQ","exam":"EOT · 10G3 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 729 · Q4 · Completing the square · إكمال المربع","prompt":"Which value of c and binomial square complete $x^2+17x+c$ correctly?","promptAr":"أي قيمة لـ c وصورة مربع ذي الحدين تكمل $x^2+17x+c$ بصورة صحيحة؟","answer":"$c=(\\frac{17}{2})^2=\\frac{289}{4}=72.25$. Hence $x^2+17x+\\frac{289}{4}=(x+\\frac{17}{2})^2$.","answerAr":"$c=(\\frac{17}{2})^2=\\frac{289}{4}=72.25$. ومنه $x^2+17x+\\frac{289}{4}=(x+\\frac{17}{2})^2$.","marks":1,"diagram":"none","difficulty":"Standard","image":"","options":["$c=72.25,\\quad (x-8.5)^2$","$c=18.0625,\\quad (x+4.25)^2$","$c=72.25,\\quad (x+8.5)^2$","$c=289,\\quad (x+17)^2$"],"optionsAr":["$c=72.25,\\quad (x-8.5)^2$","$c=18.0625,\\quad (x+4.25)^2$","$c=72.25,\\quad (x+8.5)^2$","$c=289,\\quad (x+17)^2$"],"sourcePage":729,"sourceQuestion":4,"expectedValues":{"c":72.25},"problemData":{"kind":"complete-square","b":17,"c":72.25,"shift":8.5},"squareChoices":[[72.25,-8.5],[18.0625,4.25],[72.25,8.5],[289,17]],"correctIndex":2}$question_json$::jsonb),
('10g3-w9-p729-q5',$question_json${"id":"10g3-w9-p729-q5","classroom":"10G3","examWeek":9,"position":13,"type":"MCQ","exam":"EOT · 10G3 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 729 · Q5 · Completing the square · إكمال المربع","prompt":"Which value of c and binomial square complete $x^2+5x+c$ correctly?","promptAr":"أي قيمة لـ c وصورة مربع ذي الحدين تكمل $x^2+5x+c$ بصورة صحيحة؟","answer":"$c=(\\frac{5}{2})^2=\\frac{25}{4}=6.25$. Hence $x^2+5x+\\frac{25}{4}=(x+\\frac{5}{2})^2$.","answerAr":"$c=(\\frac{5}{2})^2=\\frac{25}{4}=6.25$. ومنه $x^2+5x+\\frac{25}{4}=(x+\\frac{5}{2})^2$.","marks":1,"diagram":"none","difficulty":"Standard","image":"","options":["$c=25,\\quad (x+5)^2$","$c=6.25,\\quad (x-2.5)^2$","$c=1.5625,\\quad (x+1.25)^2$","$c=6.25,\\quad (x+2.5)^2$"],"optionsAr":["$c=25,\\quad (x+5)^2$","$c=6.25,\\quad (x-2.5)^2$","$c=1.5625,\\quad (x+1.25)^2$","$c=6.25,\\quad (x+2.5)^2$"],"sourcePage":729,"sourceQuestion":5,"expectedValues":{"c":6.25},"problemData":{"kind":"complete-square","b":5,"c":6.25,"shift":2.5},"squareChoices":[[25,5],[6.25,-2.5],[1.5625,1.25],[6.25,2.5]],"correctIndex":3}$question_json$::jsonb),
('10g3-w9-p729-q6',$question_json${"id":"10g3-w9-p729-q6","classroom":"10G3","examWeek":9,"position":14,"type":"MCQ","exam":"EOT · 10G3 · Week 9 Practice · تدريب الأسبوع التاسع","topic":"Page 729 · Q6 · Completing the square · إكمال المربع","prompt":"Which value of c and binomial square complete $x^2-13x+c$ correctly?","promptAr":"أي قيمة لـ c وصورة مربع ذي الحدين تكمل $x^2-13x+c$ بصورة صحيحة؟","answer":"$c=(\\frac{-13}{2})^2=\\frac{169}{4}=42.25$. Hence $x^2-13x+\\frac{169}{4}=(x-\\frac{13}{2})^2$.","answerAr":"$c=(\\frac{-13}{2})^2=\\frac{169}{4}=42.25$. ومنه $x^2-13x+\\frac{169}{4}=(x-\\frac{13}{2})^2$.","marks":1,"diagram":"none","difficulty":"Standard","image":"","options":["$c=42.25,\\quad (x-6.5)^2$","$c=169,\\quad (x-13)^2$","$c=42.25,\\quad (x+6.5)^2$","$c=10.5625,\\quad (x-3.25)^2$"],"optionsAr":["$c=42.25,\\quad (x-6.5)^2$","$c=169,\\quad (x-13)^2$","$c=42.25,\\quad (x+6.5)^2$","$c=10.5625,\\quad (x-3.25)^2$"],"sourcePage":729,"sourceQuestion":6,"expectedValues":{"c":42.25},"problemData":{"kind":"complete-square","b":-13,"c":42.25,"shift":-6.5},"squareChoices":[[42.25,-6.5],[169,-13],[42.25,6.5],[10.5625,-3.25]],"correctIndex":0}$question_json$::jsonb)
